package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"sort"
	"strings"

	"github.com/LeXwDeX/tribunal/internal/config"
	"github.com/LeXwDeX/tribunal/internal/gitlab"
	"github.com/LeXwDeX/tribunal/internal/jobs"
	"github.com/LeXwDeX/tribunal/internal/secret"
	"github.com/LeXwDeX/tribunal/internal/store"
	"github.com/LeXwDeX/tribunal/internal/workspace"
)

const (
	developerAccess = 30

	// commandReplyMarkerPrefix is reserved for replies generated by this
	// worker. It is deliberately separate from the review summary marker so
	// reply scans and summary scans cannot match each other.
	commandReplyMarkerPrefix = "<!-- gitlab-ce-review:command-reply"
	permissionReplyText      = "需要 Developer（30）及以上权限才能使用 `/review` 命令。"
)

// CommandGitLab is the subset of GitLab used to validate a command and publish
// its reply. Production passes gitlab.Client; tests inject a fake.
type CommandGitLab interface {
	gitlab.API
	ListMRNotes(ctx context.Context, token string, projectID, iid int64) ([]gitlab.Note, error)
	CreateMRNote(ctx context.Context, token string, projectID, iid int64, body string) (*gitlab.Note, error)
	UpdateMRNote(ctx context.Context, token string, projectID, iid, noteID int64, body string) error
	ListNoteAwards(ctx context.Context, token string, projectID, iid, noteID int64) ([]gitlab.Award, error)
	AddNoteAward(ctx context.Context, token string, projectID, iid, noteID int64, name string) (*gitlab.Award, error)
	DeleteNoteAward(ctx context.Context, token string, projectID, iid, noteID, awardID int64) error
}

// CommandStore is the persistence surface needed by CommandWorker. The enqueue
// transaction owns the generation and the durable status/reaction goals, so a
// command cannot leave a pre-enqueue reaction behind after a failed write.
type CommandStore interface {
	GetProject(ctx context.Context, id int64) (*store.Project, error)
	GetJob(ctx context.Context, id string) (*store.Job, error)
	EnqueueReviewLatest(ctx context.Context, command store.ReviewCommand) (store.ReviewEnqueueResult, error)
}

// CommandWorker revalidates `/review` note commands and only then enqueues a
// review run or cancel. Help and denied authors receive one idempotent reply,
// keyed by the source note.
type CommandWorker struct {
	store        CommandStore
	workspace    *workspace.Manager
	gitlab       CommandGitLab
	cipher       *secret.Cipher
	profiles     map[string]config.ProfileConfig
	botUsernames map[string]bool
	logger       *slog.Logger
}

// CommandWorkerConfig configures CommandWorker.
type CommandWorkerConfig struct {
	Store        CommandStore
	Workspace    *workspace.Manager
	GitLab       CommandGitLab
	Cipher       *secret.Cipher
	Profiles     map[string]config.ProfileConfig
	BotUsernames []string
	Logger       *slog.Logger
}

// NewCommandWorker builds the bounded M0 command handler.
func NewCommandWorker(cfg CommandWorkerConfig) (*CommandWorker, error) {
	if cfg.Store == nil || cfg.GitLab == nil || cfg.Cipher == nil || cfg.Workspace == nil {
		return nil, errors.New("app: command worker dependencies are required")
	}
	logger := cfg.Logger
	if logger == nil {
		logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	bots := make(map[string]bool, len(cfg.BotUsernames))
	for _, name := range cfg.BotUsernames {
		if name != "" {
			bots[name] = true
		}
	}
	return &CommandWorker{
		store:        cfg.Store,
		workspace:    cfg.Workspace,
		gitlab:       cfg.GitLab,
		cipher:       cfg.Cipher,
		profiles:     cfg.Profiles,
		botUsernames: bots,
		logger:       logger,
	}, nil
}

type commandPayload struct {
	ProjectID       int64  `json:"project_id"`
	MRIID           int64  `json:"mr_iid"`
	NoteID          int64  `json:"note_id"`
	AuthorID        int64  `json:"author_id"`
	AuthorUsername  string `json:"author_username"`
	AuthorBot       bool   `json:"author_bot"`
	Command         string `json:"command"`
	Profile         string `json:"profile"`
	ProfileExplicit *bool  `json:"profile_explicit,omitempty"`
	Full            bool   `json:"full"`
	Trigger         string `json:"trigger"`
}

// Handle implements jobs.Handler for review.command. Returning nil settles the
// job as done; returning an error lets the worker retry with backoff.
func (w *CommandWorker) Handle(ctx context.Context, job *jobs.Job) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if job == nil || job.Kind != "review.command" {
		return nil
	}
	var payload commandPayload
	dec := json.NewDecoder(strings.NewReader(string(job.Payload)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&payload); err != nil {
		return nil
	}
	if payload.ProjectID <= 0 || payload.MRIID <= 0 || payload.NoteID <= 0 ||
		payload.AuthorID <= 0 || (payload.Command != commandRun && payload.Command != commandCancel && payload.Command != commandHelp) {
		return nil
	}
	unlock, err := w.workspace.Get(payload.ProjectID).LifecycleRLock(ctx)
	if err != nil {
		return err
	}
	defer unlock()
	if err := consumerJobExists(ctx, w.store, job, "review.command", payload.ProjectID); err != nil {
		if IsPermanentJob(err) {
			return nil
		}
		return err
	}

	project, err := w.store.GetProject(ctx, payload.ProjectID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return nil
		}
		return err
	}
	if project == nil || !project.Enabled {
		return nil
	}
	if payload.AuthorBot || w.botUsernames[payload.AuthorUsername] {
		return nil
	}
	token, err := w.cipher.Open(project.TokenEnc, secret.TokenAAD(project.ID))
	if err != nil {
		w.logger.Warn("command worker could not decrypt project token", "project_id", project.ID)
		return errors.New("app: project token unavailable")
	}

	current, err := w.gitlab.CurrentUser(ctx, string(token))
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return err
		}
		return errors.New("app: cannot verify bot identity")
	}
	if current != nil && (current.ID == payload.AuthorID || (payload.AuthorUsername != "" && current.Username == payload.AuthorUsername)) {
		return nil
	}

	mr, err := w.gitlab.GetMergeRequest(ctx, string(token), project.ID, payload.MRIID)
	if err != nil {
		if gitlab.IsNotFound(err) {
			return nil
		}
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return err
		}
		return errors.New("app: cannot read merge request")
	}
	if mr == nil || !isOpenState(mr.State) {
		return nil
	}
	if mr.TargetProjectID > 0 && mr.TargetProjectID != project.ID {
		return nil
	}

	access, err := w.gitlab.GetMemberAccess(ctx, string(token), project.ID, payload.AuthorID)
	if err != nil {
		if !gitlab.IsNotFound(err) {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				return err
			}
			return errors.New("app: cannot verify command author access")
		}
		// The inherited-members endpoint returns 404 for non-members. Only
		// treat it as a definitive denial after the MR was read successfully.
		access = 0
	}
	replyAuthorID := int64(0)
	if current != nil {
		replyAuthorID = current.ID
	}
	if access < developerAccess {
		return w.reply(ctx, string(token), project, payload, replyAuthorID, "denied", permissionReplyText)
	}
	if payload.Command == commandHelp {
		return w.reply(ctx, string(token), project, payload, replyAuthorID, "help", helpReplyText(w.profiles))
	}

	if payload.Command == commandRun {
		sha := strings.TrimSpace(mr.SHA)
		if !shaRE.MatchString(sha) || isZeroSHA(sha) {
			return errors.New("app: merge request head SHA is unavailable")
		}
	}
	// The enqueue transaction writes the queued status and the source-note
	// eyes. A failed enqueue therefore leaves neither behind.
	if payload.Command == commandCancel {
		commandPayload := map[string]any{"project_id": project.ID, "mr_iid": payload.MRIID, "trigger": "command", "note_id": payload.NoteID, "author_id": payload.AuthorID}
		result, err := w.store.EnqueueReviewLatest(ctx, store.ReviewCommand{
			ProjectID:   project.ID,
			MRIID:       payload.MRIID,
			Cancel:      true,
			Payload:     mustJSON(commandPayload),
			MaxAttempts: 3,
		})
		if err != nil {
			return err
		}
		w.logAccepted(project.ID, payload, result.JobID, result.Duplicate)
		return nil
	}

	profile := payload.Profile
	if _, ok := w.profiles[profile]; !ok {
		profile = project.Profile
	}
	if _, ok := w.profiles[profile]; !ok {
		profile = "default"
	}
	explicit := true
	if payload.ProfileExplicit != nil {
		explicit = *payload.ProfileExplicit
	}
	runPayload := map[string]any{
		"project_id":       project.ID,
		"mr_iid":           payload.MRIID,
		"head_sha":         strings.ToLower(strings.TrimSpace(mr.SHA)),
		"profile":          profile,
		"profile_explicit": explicit,
		"trigger":          "command",
		"full":             payload.Full,
		"note_id":          payload.NoteID,
	}
	result, err := w.store.EnqueueReviewLatest(ctx, store.ReviewCommand{
		ProjectID:   project.ID,
		MRIID:       payload.MRIID,
		HeadSHA:     strings.ToLower(strings.TrimSpace(mr.SHA)),
		Payload:     mustJSON(runPayload),
		MaxAttempts: 3,
	})
	if err != nil {
		return err
	}
	w.logAccepted(project.ID, payload, result.JobID, result.Duplicate)
	return nil
}

func (w *CommandWorker) reply(ctx context.Context, token string, project *store.Project, payload commandPayload, authorID int64, kind, text string) error {
	body := commandReplyBody(payload.NoteID, kind, text)
	prefix := commandReplyPrefix(payload.NoteID) + " "
	notes, err := w.gitlab.ListMRNotes(ctx, token, project.ID, payload.MRIID)
	if err != nil {
		return w.replyError(ctx, err)
	}
	for _, note := range notes {
		if !strings.HasPrefix(note.Body, prefix) {
			continue
		}
		if authorID > 0 && note.AuthorID != authorID {
			continue
		}
		if note.Body == body {
			return nil
		}
		if err := w.gitlab.UpdateMRNote(ctx, token, project.ID, payload.MRIID, note.ID, body); err != nil {
			return w.replyError(ctx, err)
		}
		return nil
	}
	if _, err := w.gitlab.CreateMRNote(ctx, token, project.ID, payload.MRIID, body); err != nil {
		return w.replyError(ctx, err)
	}
	return nil
}

func (w *CommandWorker) replyError(ctx context.Context, err error) error {
	if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return err
	}
	w.logger.Warn("command reply failed")
	return errors.New("app: cannot publish command reply")
}

func commandReplyPrefix(noteID int64) string {
	return fmt.Sprintf("%s note=%d", commandReplyMarkerPrefix, noteID)
}

func commandReplyMarker(noteID int64, kind string) string {
	marker := commandReplyPrefix(noteID)
	if kind != "" {
		marker += " kind=" + kind
	}
	return marker + " v1 -->"
}

func commandReplyBody(noteID int64, kind, text string) string {
	return commandReplyMarker(noteID, kind) + "\n" + text
}

func isCommandReplyBody(body string) bool {
	return strings.HasPrefix(body, commandReplyMarkerPrefix)
}

func helpReplyText(profiles map[string]config.ProfileConfig) string {
	names := make([]string, 0, len(profiles))
	for name := range profiles {
		names = append(names, name)
	}
	sort.Strings(names)
	available := "（无）"
	if len(names) > 0 {
		available = "`" + strings.Join(names, "`、`") + "`"
	}
	return "**可用命令**\n\n" +
		"- `/review`：使用项目默认档位重新评审（增量）\n" +
		"- `/review full`：全量评审\n" +
		"- `/review <profile>`：指定档位，例如 `/review deep`\n" +
		"- `/review cancel`：取消正在运行的评审\n" +
		"- `/review help`：显示本说明\n\n" +
		"可用档位（按名称排序）：" + available
}

func (w *CommandWorker) logAccepted(projectID int64, payload commandPayload, jobID string, duplicate bool) {
	w.logger.Info("review command accepted",
		"project_id", projectID,
		"mr_iid", payload.MRIID,
		"command", payload.Command,
		"job_id", jobID,
		"duplicate", duplicate,
	)
}

func mustJSON(value any) json.RawMessage {
	encoded, err := json.Marshal(value)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return encoded
}
